from collections.abc import Callable
from typing import Any

CALLS: list[str] = []


def shout(func: Callable[..., Any]) -> Callable[..., Any]:
    def wrapper(*args: Any, **kwargs: Any) -> Any:
        return func(*args, **kwargs).upper()
    return wrapper


def trace(func: Callable[..., Any]) -> Callable[..., Any]:
    def wrapper(*args: Any, **kwargs: Any) -> Any:
        CALLS.append(func.__name__)
        return func(*args, **kwargs)
    return wrapper


# Supplied. Put one decorator line above it. Do not change the body.
@shout
def greet(name: str) -> str:
    """Greet the named person."""
    return f"hi {name}"


# Supplied. Put one decorator line above it. Do not change the body.
@trace
def add(left: int, right: int) -> int:
    """Add two whole numbers."""
    return left + right

testcode.text:
@shout
def cheer(name: str) -> str:
    return f"go {name}"


def chant(name: str) -> str:
    return f"go {name}"


chant = shout(chant)
print(cheer("ada"))
print(chant("ada"))
print(cheer("ada") == chant("ada"))
print(cheer.__name__, chant.__name__)

question.answer:
import functools
from collections.abc import Callable
from typing import Any

LOG: list[str] = []
ATTEMPTS: list[str] = []
PENDING_FAILURES = 2


# Supplied. Do not change this exception.
class SensorError(Exception):
    pass


def audit(channel: str) -> Callable[[Callable[..., Any]], Callable[..., Any]]:
    def decorate(func: Callable[..., Any]) -> Callable[..., Any]:
        @functools.wraps(func)
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            LOG.append(f"{channel}: calling {func.__name__}")
            result = func(*args, **kwargs)
            LOG.append(f"{channel}: {func.__name__} returned {result!r}")
            return result
        return wrapper
    return decorate


def retry(times: int) -> Callable[[Callable[..., Any]], Callable[..., Any]]:
    def decorate(func: Callable[..., Any]) -> Callable[..., Any]:
        @functools.wraps(func)
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            last = None
            for _ in range(times):
                try:
                    return func(*args, **kwargs)
                except SensorError as exc:
                    last = exc
            raise last
        return wrapper
    return decorate


# Supplied. Put the two decorator lines above it. Do not change the body.
@audit("ops")
@retry(3)
def read_sensor(name: str) -> str:
    """Read the named sensor and return its reading."""
    global PENDING_FAILURES
    ATTEMPTS.append(name)
    if PENDING_FAILURES > 0:
        PENDING_FAILURES -= 1
        raise SensorError(f"{name} not ready")
    return f"{name}=42"

testcode.text:
ATTEMPTS.clear()
LOG.clear()
PENDING_FAILURES = 99
try:
    read_sensor("t2")
except SensorError as exc:
    print("escaped:", type(exc).__name__, exc)
print(len(ATTEMPTS))
for line in LOG:
    print(line)

question.answer:
import functools
from collections.abc import Callable, Iterator
from typing import Any, Protocol, runtime_checkable

LOG: list[str] = []


# Supplied from the previous tier. Do not change it.
def audit(channel: str) -> Callable[[Callable[..., Any]], Callable[..., Any]]:
    def decorate(func: Callable[..., Any]) -> Callable[..., Any]:
        @functools.wraps(func)
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            LOG.append(f"{channel}: calling {func.__name__}")
            return func(*args, **kwargs)
        return wrapper
    return decorate


class Recorder:
    """Wrap any object and record every name that passes through the wrapper."""

    def __init__(self, target: object) -> None:
        self.target = target
        self.seen: list[str] = []

    def __getattr__(self, name: str) -> Any:
        self.seen.append(name)
        return getattr(self.target, name)

    # isinstance(Recorder([]), list) is False and stays False. Forwarding is not
    # inheritance, so any caller that tests the concrete type rejects the wrapper.
    def __len__(self) -> int:
        self.seen.append("__len__")
        return len(self.target)

    def __getitem__(self, index: object) -> Any:
        self.seen.append("__getitem__")
        return self.target[index]

    def __iter__(self) -> Iterator[Any]:
        self.seen.append("__iter__")
        return iter(self.target)

    def __call__(self, *args: Any, **kwargs: Any) -> Any:
        self.seen.append("__call__")
        return self.target(*args, **kwargs)


@runtime_checkable
class Clock(Protocol):
    def now(self) -> str:
        ...


class SystemClock:
    def now(self) -> str:
        import datetime
        return datetime.datetime.now().isoformat(timespec="seconds")


class FrozenClock:
    def __init__(self, stamp: str = "2026-01-01T09:00:00") -> None:
        self.stamp = stamp

    def now(self) -> str:
        return self.stamp


class AuditLog:
    def __init__(self, clock: Clock) -> None:
        self.clock = clock
        self.entries: list[str] = []

    def record(self, message: str) -> str:
        entry = f"{self.clock.now()} {message}"
        self.entries.append(entry)
        return entry


# Supplied. Put @Recorder above @audit("ops"). Do not change the body.
@Recorder
@audit("ops")
def scale(reading: int) -> int:
    """Multiply a reading by ten."""
    return reading * 10
